const allItems = $input.all();

// ==================== 1. Récupération de config_ia ====================
let configIa = { criteres: [] };
for (const item of allItems) {
  const json = item.json || {};
  const candidates = [json.config_ia, json.body?.config_ia];
  for (const source of candidates) {
    if (source && Array.isArray(source.criteres)) {
      configIa = {
        criteres: source.criteres.map(c => ({
          nom: c.nom || '',
          description: c.description || '',
          pertinence_forte_si: c.pertinence_forte_si || ''
        }))
      };
      break;
    }
  }
  if (configIa.criteres.length > 0) break;
}

// ==================== 2. Extraction des offres depuis le champ text ====================
function tryParseJson(str) {
  try { return JSON.parse(str); } catch (e) { return null; }
}

// Extrait le bloc JSON de l'offre depuis le texte formaté
function extractOffreFromText(text) {
  if (typeof text !== 'string') return null;
  const marker = '=== NOUVEAU MARCHÉ À ÉVALUER ===';
  const idx = text.indexOf(marker);
  if (idx === -1) return null;
  const jsonPart = text.slice(idx + marker.length).trim();
  return tryParseJson(jsonPart);
}

// Reconstruit un texte propre : historique + config_ia + offre
function extractHistoriqueFromText(text) {
  if (typeof text !== 'string') return '';
  const marker = '=== NOUVEAU MARCHÉ À ÉVALUER ===';
  const idx = text.indexOf(marker);
  if (idx === -1) return text;
  return text.slice(0, idx).trim();
}

// ==================== 3. Traitement de chaque item ====================
const resultats = [];

for (const item of allItems) {
  const json = item.json || {};
  const text = json.text || '';

  // Cas A : le texte contient déjà "=== NOUVEAU MARCHÉ À ÉVALUER ===" → offre déjà intégrée
  if (text.includes('=== NOUVEAU MARCHÉ À ÉVALUER ===')) {
    const offre = extractOffreFromText(text);
    const historique = extractHistoriqueFromText(text);
    const configJson = JSON.stringify(configIa, null, 2);

    const texteComplet = `${historique}

=== CRITÈRES D'ÉVALUATION ===
${configJson}

