// ==================== PARSERS ====================
function parsePertinence(item) {
  try {
    const raw = item?.json?.text || "";
    const cleaned = raw.replace(/```json\s*/g, '').replace(/```\s*/g, '').trim();
    return JSON.parse(cleaned);
  } catch(e) { 
    console.log('❌ Erreur parsing pertinence:', e.message);
    return {}; 
  }
}

function parseOffre(item) {
  try {
    const raw = item?.json?.text || "";

    // Cas 1 : tableau JSON stringifié
    if (raw.trim().startsWith('[')) {
      const arr = JSON.parse(raw.trim());
      return Array.isArray(arr) ? arr[0] : arr;
    }

    // Cas 2 : marqueur spécifique
    const marker = '=== NOUVEAU MARCHÉ À ÉVALUER ===';
    const idx = raw.indexOf(marker);
    if (idx !== -1) {
      return JSON.parse(raw.slice(idx + marker.length).trim());
    }

    // Cas 3 : JSON simple
    return JSON.parse(raw.trim());
  } catch(e) {
    // Fallback sur l'objet json direct
    const j = item?.json || {};
    if (j.name && (j.date_deadline || j.company_name)) return j;
    console.log('❌ Erreur parsing offre:', e.message);
    return {};
  }
}

